int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, S;
    cin >> N >> S;

    vector<long long> freq(10LL * N + 1, 0);
    freq[0] = 1;

    long long prefix = 0;
    long long answer = 0;

    for (int i = 0; i < N; ++i) {
        int x;
